INSERT INTO modules (module_key,name,description,sort_order) VALUES ('tax_configuration','Tax','Configure salary tax withholding rules.',14)
ON CONFLICT(module_key) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,sort_order=EXCLUDED.sort_order,is_active=TRUE;
INSERT INTO role_permissions(role_id,module_id,can_create,can_view,can_update,can_delete)
SELECT role.id,module.id,TRUE,TRUE,TRUE,TRUE FROM roles role CROSS JOIN modules module WHERE role.name='Administrator' AND module.module_key='tax_configuration'
ON CONFLICT(role_id,module_id) DO UPDATE SET can_create=TRUE,can_view=TRUE,can_update=TRUE,can_delete=TRUE,updated_at=NOW();
CREATE TABLE IF NOT EXISTS tax_configurations(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,effective_from DATE NOT NULL,effective_to DATE,pay_frequency TEXT NOT NULL DEFAULT 'monthly' CHECK(pay_frequency IN ('weekly','biweekly','semi_monthly','monthly')),exemption_amount NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(exemption_amount>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE IF NOT EXISTS tax_brackets(id BIGSERIAL PRIMARY KEY,configuration_id BIGINT NOT NULL REFERENCES tax_configurations(id) ON DELETE CASCADE,lower_bound NUMERIC(14,2) NOT NULL CHECK(lower_bound>=0),upper_bound NUMERIC(14,2),base_tax NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(base_tax>=0),rate_percent NUMERIC(6,3) NOT NULL CHECK(rate_percent BETWEEN 0 AND 100),CHECK(upper_bound IS NULL OR upper_bound>lower_bound),UNIQUE(configuration_id,lower_bound));
CREATE INDEX IF NOT EXISTS tax_configurations_effective_idx ON tax_configurations(is_active,effective_from,effective_to);
